node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Begin transaction
const commit = db.transaction(() => {

  // 1. Update order ORD-E0E671
  db.prepare(\`
    UPDATE orders SET
      status = 'exchange_pending',
      exchange_items = '[\"ITEM-E5801A\"]',
      exchange_new_items = '[\"PROD-B98D14\"]',
      exchange_payment_method_id = 'cc_21e6eed2',
      exchange_price_difference = -9.00,
      total_paid = 111
    WHERE order_id = 'ORD-E0E671'
  \`).run();
  console.log('✅ Order ORD-E0E671 updated');

  // 2. Update Aurora Desk Lamp stock (+1 returned)
  db.prepare(\`
    UPDATE products SET stock_quantity = stock_quantity + 1
    WHERE product_id = 'PROD-73FAB4'
  \`).run();
  console.log('✅ Aurora Smart Desk Lamp Pro inventory updated (24 → 25)');

  // 3. Anker speaker — no stock change (backorder)
  console.log('✅ Anker Portable Bluetooth Speaker — backorder placed (stock unchanged)');

});

commit();

// Verify all changes
console.log('\n── VERIFICATION ──────────────────────────────────────────────');

const order = db.prepare(\"SELECT status, exchange_items, exchange_new_items, exchange_payment_method_id, exchange_price_difference, total_paid FROM orders WHERE order_id = 'ORD-E0E671'\").get();
console.log('Order:', JSON.stringify(order));

const lamp = db.prepare(\"SELECT product_id, name, stock_quantity FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('Lamp stock:', JSON.stringify(lamp));

const speaker = db.prepare(\"SELECT product_id, name, stock_quantity, backorder_available FROM products WHERE product_id = 'PROD-B98D14'\").get();
console.log('Speaker stock:', JSON.stringify(speaker));
"

